const SOUTH='https://www.southviewpreservation.com/';
const VISUALS={
 freedom:{file:'freedom.jpg',caption:'General Order No. 3, June 19, 1865 · National Archives. Texas document shown as emancipation context.',url:'https://www.archives.gov/news/articles/juneteenth-original-document',fit:'contain'},
 massacre:{file:'barbershop.jpg',caption:'Herndon’s barbershop, 1903 · Kenan Research Center / Digital Library of Georgia. Photographed before the 1906 attack.',url:'https://dlg.usg.edu/record/geh_athpc_1190',fit:'contain'},
 selma:{file:'selma.jpg',caption:'Selma to Montgomery march, 1965 · Peter Pettus / Library of Congress, via National Park Service. The broader march, not the March 7 attack.',url:'https://home.nps.gov/articles/selmatomongtomerymarch.htm',fit:'cover'},
 education:{file:'education.svg',caption:'Original visual interpretation · education and opportunity. Not an archival photograph.',fit:'cover'},
 civic:{file:'civic.svg',caption:'Original visual interpretation · representation and civic life. Not an archival document.',fit:'cover'},
 business:{file:'business.svg',caption:'Original visual interpretation · Black enterprise and community. Not an archival document.',fit:'cover'},
 community:{file:'community.svg',caption:'Original visual interpretation · community institutions. Not an archival photograph.',fit:'cover'},
 children:{file:'children.svg',caption:'Original commemorative visual · Atlanta, 1979–1981. Not an archival photograph.',url:'https://www.fbi.gov/history/field-office-histories/atlanta',fit:'cover'}
};
function chapter(date,title,text,visual,kind='Documented life history',source=null){return {date,title,text,visual,kind,source};}
const STORY_PEOPLE=[
 {id:'benjaminemays',name:'Benjamin E. Mays',role:'Educator & civil rights leader',group:'Education',credit:'Portrait via Historic South-View.',intro:'Benjamin E. Mays helped shape Atlanta’s educational and civic life. His leadership at Morehouse College and the Atlanta Board of Education connected education to the struggle for social change. His story is also one of partnership: South-View remembers his wife, Sadie Gray Mays, alongside him.',chapters:[
 chapter('20TH CENTURY','Education as a force for change.','Mays helped transform Morehouse College into a place for Black leadership. At the Atlanta Board of Education, his work brought the purpose of education into the city’s public life. These institutions place his story within the broader struggle for educational opportunity.','education'),
 chapter('CIVIL RIGHTS ERA','A community’s future, in the classroom.','South-View identifies Mays as an educator and civil rights leader. His contributions offer a way to understand the relationship between education and social change. This is a connection through his documented work, rather than a claim that he personally experienced the project’s 1865 or 1906 events.','civic','Historical context')],legacy:'Mays’s legacy includes the schools he helped shape and the work he shared with Sadie Gray Mays. A life in the archive holds relationships and institutions as well as public accomplishments.'},
 {id:'williamhcrogman',name:'William H. Crogman',role:'Educator & civic leader',group:'Education',credit:'Portrait via Historic South-View.',intro:'William H. Crogman was an educator and civic leader whose work helped build Atlanta’s intellectual life. South-View remembers his commitment to academic excellence and character development in the Black community.',chapters:[
 chapter('EDUCATION & CIVIC LIFE','Learning creates possibilities.','Crogman’s institutional leadership supported educational progress and civic growth. His story brings us into the work of building institutions where Black students could develop their abilities and take part in community life.','education'),
 chapter('THE LARGER HISTORY','The promise of opportunity.','Education is one way to explore the broader legacy of emancipation. Juneteenth commemorates the June 19, 1865 announcement of freedom in Galveston, Texas. Crogman’s education work is presented here as thematic context; the sources used do not place him at that announcement.','freedom','Thematic context','https://nmaahc.si.edu/explore/stories/what-juneteenth')],legacy:'His story keeps the everyday work of teaching and institution building within view. South-View’s profile provides the starting point for learning more about his life.'},
 {id:'robertgrant',name:'Robert Grant',role:'Blacksmith, drayman & faith leader',group:'Community',credit:'Courtesy of Zion Hill Baptist Church, via Historic South-View.',intro:'Robert Grant brought together skilled labor and spiritual leadership. A blacksmith and drayman, he founded Zion Hill Baptist Church. His work helps us see the people behind the institutions of post-Civil War Black Atlanta.',chapters:[
 chapter('POST-CIVIL WAR ATLANTA','Building a place to belong.','Grant’s founding of Zion Hill Baptist Church is part of his documented life. The church provided an institution around which community could form. His working life and religious leadership belong together in his story.','community'),
 chapter('1865 & RECONSTRUCTION','What would freedom make possible?','Juneteenth marks the announcement of freedom in Galveston, Texas, on June 19, 1865. Grant’s story connects to the broader work of community building after the Civil War. This is Reconstruction context, not evidence that he took part in the Texas event.','freedom','Reconstruction context','https://nmaahc.si.edu/explore/stories/what-juneteenth')],legacy:'A church founder was also a worker and a community member. Remembering Grant makes room for the labor and service that built Atlanta’s institutions.'},
 {id:'gracetownshamilton',name:'Grace Towns Hamilton',role:'Civil rights leader & legislator',group:'Civil rights',credit:'Via Wikimedia Commons, as credited by Historic South-View.',intro:'Grace Towns Hamilton was a civil rights leader whose public service broke racial and gender barriers. South-View remembers her advocacy for education reform, social justice, and equal opportunity.',chapters:[
 chapter('GEORGIA GENERAL ASSEMBLY','A place in public decision-making.','Hamilton became the first Black woman elected to the Georgia General Assembly. Her election brought a new voice into state government and opened space for greater representation. This is a milestone in her own life, not simply background history.','civic'),
 chapter('EDUCATION & EQUALITY','Public service reaches everyday life.','Her career joined representation with advocacy for education and marginalized communities. Through Hamilton, a large story about political opportunity becomes a story about the work of a particular public servant.','education')],legacy:'Hamilton’s life links persistence and public office to the needs of a community. Her contributions continue to offer a way to think about who gets represented and heard.'},
 {id:'alonzoherndon',name:'Alonzo Herndon',role:'Entrepreneur & community builder',group:'Business',credit:'Portrait via Historic South-View.',intro:'Alonzo Herndon was a barber and entrepreneur who built the company that became Atlanta Life Insurance. His work supported Black economic independence, employment, and community institutions. Begin with that fuller life before entering the events that shaped it.',chapters:[
 chapter('1865','Freedom was a beginning.','Herndon was emancipated as a child in Georgia at the end of the Civil War. Juneteenth commemorates freedom’s announcement in Texas that year. His life connects directly to emancipation, while the Texas document shown here gives broader context; it does not place him in Galveston.','freedom','Emancipation experienced in Georgia','https://www.georgiaencyclopedia.org/articles/business-economy/alonzo-herndon-1858-1927/'),
 chapter('SEPTEMBER 1906','A livelihood in the path of violence.','During the Atlanta Race Massacre, white mobs smashed the windows of Herndon’s Peachtree Street barbershop. He had already gone home. The photograph shows the shop in 1903, before the attack: a place of work and ambition within a city facing racial violence.','massacre','Documented event connection','https://www.georgiaencyclopedia.org/articles/history-archaeology/atlanta-race-massacre-of-1906/')],legacy:'Herndon’s story continues through business and family. His wife Adrienne was an educator, and their son Norris carried on the insurance enterprise. He deserves to be remembered for what he built as well as what his business endured.',extraSource:'https://www.georgiaencyclopedia.org/articles/business-economy/alonzo-herndon-1858-1927/'},
 {id:'annielmcpheeters',name:'Annie L. McPheeters',role:'Librarian & civil rights activist',group:'Education',credit:'Courtesy of Auburn Avenue Research Library, via Historic South-View.',intro:'Annie L. McPheeters dedicated her career to literacy and access to books and historical information. One of Atlanta’s early Black librarians, she moved to the city for her education and worked to make knowledge more accessible to others.',chapters:[
 chapter('ATLANTA’S LIBRARIES','Books should be within reach.','McPheeters developed programs to increase literacy and library use in the Black community. Her daily work helped connect readers with information, learning, and the history of their community.','education'),
 chapter('DESEGREGATION','Opening a public institution.','She worked with Black advocacy groups to help end segregation in Atlanta public libraries. South-View also identifies her as the first African American reference librarian at Georgia State College. These documented experiences place her within the struggle for equal access.','civic')],legacy:'Her legacy holds both activism and the patient work of a librarian: supporting readers, building literacy, and helping people encounter their history.'},
 {id:'johnwdobbs',name:'John W. Dobbs',role:'Civic & political leader',group:'Civil rights',credit:'Portrait via Historic South-View.',intro:'John Wesley Dobbs was a civic leader rooted in Atlanta’s Sweet Auburn community. Born in Kennesaw in 1882, he became a voice for civil rights and political participation, linking neighborhood life with the ability to take part in public decisions.',chapters:[
 chapter('SWEET AUBURN','A neighborhood becomes a center.','Dobbs earned the honorary title “Mayor of Auburn Avenue.” South-View describes his work in helping Sweet Auburn grow as a center of Black business and culture. His story brings people, institutions, and a neighborhood into the same frame.','business'),
 chapter('POLITICAL PARTICIPATION','Making a voice count.','A founding member of the Atlanta Civic and Political League, Dobbs worked to register Black voters. This was a direct part of his civic work: the effort to make political participation available to more people.','civic')],legacy:'Dobbs’s contributions connect the life of a neighborhood to public power. His story includes community building as well as the struggle for civil rights.'},
 {id:'grahamwjacksonsr',name:'Graham W. Jackson Sr.',role:'Musician & performer',group:'Arts',credit:'Photo via Syncopated Times, as credited by Historic South-View.',intro:'Graham W. Jackson Sr. was a musician whose talents included the organ, piano, and accordion. His career brought national recognition to an artist within Atlanta’s Black community during an era of segregation.',chapters:[
 chapter('1945','Music at a moment of national loss.','South-View remembers Jackson for playing “Going Home” on the accordion in connection with President Franklin D. Roosevelt’s funeral in 1945. His performance became an enduring image of that historical moment.','portrait','Documented event connection'),
 chapter('AN ERA OF SEGREGATION','A career larger than one photograph.','Jackson’s life was also the work of a performer and musician. His artistic accomplishment belongs alongside the widely remembered funeral image. The symbolic visual here represents the broader community around his career, not a specific performance.','community','Historical context')],legacy:'A famous image can make a person visible and still leave much of their life unexplored. Jackson’s music and career belong in the story, too.'},
 {id:'ludieclayandrews',name:'Ludie Clay Andrews',role:'Nurse & medical pioneer',group:'Health',credit:'Portrait via Historic South-View.',intro:'Ludie Clay Andrews was a medical professional whose career challenged racial barriers in Georgia. South-View identifies her as the state’s first African American registered nurse and remembers her leadership at Spelman College’s MacVicar Hospital.',chapters:[
 chapter('GEORGIA HEALTHCARE','A barrier crossed in professional life.','Becoming a registered nurse was a personal and professional milestone for Andrews. Her career brought Black leadership into a healthcare system marked by racial exclusion.','civic'),
 chapter('MACVICAR HOSPITAL','Care also builds a future.','Her decades of leadership at Spelman’s MacVicar Hospital helped establish a foundation for later Black healthcare providers. Her story links care for patients with opportunity for future professionals.','education')],legacy:'Andrews’s life reminds us that historical change also happens through professional work, service, and the institutions that train the next generation.'},
 {id:'bazolineeusher',name:'Bazoline E. Usher',role:'Educator & school leader',group:'Education',credit:'Via Wikimedia Commons, as credited by Historic South-View.',intro:'Bazoline E. Usher spent forty years in Atlanta Public Schools. Her work expanded opportunity for Black students and educators in the segregated South. Her story connects an individual career to the institutions of a city.',chapters:[
 chapter('SEGREGATED SCHOOLS','Opportunity begins in a classroom.','Usher’s educational work challenged barriers facing Black students and faculty. South-View remembers her long career as one that helped shape the future of Black education in Atlanta.','education'),
 chapter('ATLANTA CITY HALL','Leadership enters a new space.','South-View identifies Usher as the first African American to hold an office in Atlanta City Hall. That milestone links her educational career with civic life and the expansion of opportunity in the city.','civic')],legacy:'Her life holds the long, cumulative work of an educator. Institutional milestones matter, and so do the students and faculty her career served.'},
 {id:'johnlewis',name:'John Lewis',role:'Civil rights activist & statesman',group:'Civil rights',credit:'SEIU Local 721 / Public Domain, as credited by Historic South-View.',intro:'John Lewis was a civil rights activist and later a longtime representative of Georgia’s 5th Congressional District. As a young leader of the Student Nonviolent Coordinating Committee, he helped organize sit-ins and voter registration efforts.',chapters:[
 chapter('MARCH 7, 1965','Across the bridge at Selma.','Lewis helped lead marchers across the Edmund Pettus Bridge. State troopers attacked the marchers in the event remembered as Bloody Sunday. The photograph shows the broader Selma-to-Montgomery movement later that month; it is not an image of the attack.','selma','Documented event connection','https://www.nps.gov/semo/learn/historyculture/bloody-sunday.htm'),
 chapter('1965 & BEYOND','From voting rights to public service.','The Selma campaign helped build support for the Voting Rights Act of 1965. Lewis later served for more than thirty years in Congress. The story moves from a specific march to a long life of advocacy for civil rights and democracy.','civic','Documented life history','https://home.nps.gov/articles/selmatomongtomerymarch.htm')],legacy:'The bridge is one chapter in Lewis’s life. Organizing, voting rights, and decades of public service make up the larger story remembered by South-View.'},
 {id:'mosesamos',name:'Dr. Moses Amos',role:'Pharmacist & entrepreneur',group:'Health',credit:'Courtesy of Association of Black Health-System Pharmacists, via Historic South-View.',intro:'Born free in Georgia in 1866, Moses Amos became the state’s first licensed Black pharmacist. His career began in apprenticeship and grew into pharmacy management, ownership, and mentorship of other medical professionals.',chapters:[
 chapter('1914','A pharmacy of his own.','After working under other doctors and managing a drugstore, Amos bought the business and named it the Gate City Drug Store in 1914. Ownership was one milestone in a career that joined healthcare and enterprise.','business'),
 chapter('WORKFORCE OPPORTUNITY','Making room for the next generation.','Amos hired some of Atlanta’s early Black women clerks and trained a new generation of medical and pharmaceutical professionals. His story shows how a business could also become a place for opportunity and learning.','education')],legacy:'His legacy extends from prescriptions and pharmacy work to the people he employed and mentored. Healthcare, entrepreneurship, and community service belong together in his life.'},
 {id:'dinahwattspace',name:'Dinah Watts Pace',role:'Educator & children’s advocate',group:'Education',credit:'Portrait via Historic South-View.',intro:'Dinah Watts Pace was born into slavery and gained freedom at twelve. After moving to Atlanta, she studied at Atlanta University to become a teacher. Her later work centered the lives and needs of Black children.',chapters:[
 chapter('EMANCIPATION','A life enters freedom.','Pace’s experience of emancipation connects her life to the larger history of freedom after slavery. The Juneteenth document shown here concerns Texas; her biography does not place her at the Galveston announcement.','freedom','Emancipation experience; Texas document as context','https://nmaahc.si.edu/explore/stories/what-juneteenth'),
 chapter('1883–1884','A school, then a place of care.','Pace opened a school for Black children in 1883 and an orphanage the following year. Her work in Covington, Georgia, joined education, fundraising, and care for children. These were institutions she built within her own life.','education')],legacy:'Her story continues in the school and orphanage she established and in the park and road named for her in Covington. Her work was about children’s futures as well as her own path from slavery.'},
 {id:'freddyehenderson',name:'Freddye Henderson',role:'Entrepreneur, educator & cultural connector',group:'Business',credit:'Via BlackPast.org, as credited by Historic South-View.',intro:'Freddye Scarborough Henderson worked in fashion and travel. With her husband, she established an Atlanta travel service that helped people explore Africa and connect with their heritage. Her work linked enterprise with cultural connection.',chapters:[
 chapter('1953','Making space for Black fashion.','Henderson helped create a national organization for fashion designers and staged a major fashion show for Black audiences in 1953. Her work made room for cultural expression and professional opportunity.','business'),
 chapter('CIVIL RIGHTS ERA','Travel connected to a historic moment.','South-View credits Henderson with arranging Martin Luther King Jr.’s trip to receive his Nobel Prize. Her travel business served both well-known historical figures and everyday people seeking a connection with Africa. The visual here represents civic life, not that particular journey.','civic','Documented contribution')],legacy:'Her story joins education, entrepreneurship, and heritage. Travel was more than movement between places: it could become a way for people to encounter their history.'},
 {id:'carolyndyancey',name:'Carolyn D. Yancey',role:'Teacher & education leader',group:'Education',credit:'Courtesy of the Yancey family, via Historic South-View.',intro:'Carolyn Dunbar Yancey began as a public school teacher. She served sixteen years on the Atlanta Board of Education and became the first African American woman appointed to the University System of Georgia’s Board of Regents.',chapters:[
 chapter('EDUCATIONAL LEADERSHIP','From teaching to public decisions.','Yancey’s career joined classroom work, school governance, and higher education. Her community involvement also included the NAACP, the League of Women Voters, the Wesley Community Center, and Spelman College.','education'),
 chapter('1979–1981','The city around its children.','The Atlanta Child Murders took the lives of Black children, teenagers, and young adults. Yancey’s educational service offers a thematic lens on the institutions surrounding children. These sources do not establish that she responded directly to the crisis or knew the victims.','children','Thematic community context','https://www.fbi.gov/history/field-office-histories/atlanta')],legacy:'Yancey’s own life remains a story of teaching, civic involvement, and educational leadership. Victims’ full lives require separate research and family-informed storytelling.'},
 {id:'genevahaugabrooks',name:'Geneva Haugabrooks',role:'Entrepreneur & community advocate',group:'Business',credit:'Courtesy of Sweet Auburn Works, via Historic South-View.',intro:'Geneva Moton Haugabrooks moved to Atlanta to study at Spelman College and worked as a teacher before entering business. Her later service made her a well-known figure in the community, remembered as “Mama Haugabrooks.”',chapters:[
 chapter('1929','Building her own business.','Haugabrooks started a funeral home with less than $300 in 1929. South-View identifies her as Atlanta’s first and only Black woman funeral-home owner at that time. Her career moved from teaching into pioneering business ownership.','business'),
 chapter('COMMUNITY SERVICE','Enterprise with a public purpose.','She worked with organizations including the YMCA and Urban League and received recognition for community service. Her business life and her commitment to helping others belonged to the same larger story.','community')],legacy:'Remembering Haugabrooks means remembering a teacher, entrepreneur, and community advocate. Her work connected livelihoods with care for others.'},
 {id:'horacemannbond',name:'Horace Mann Bond',role:'Educator & education researcher',group:'Education',credit:'Via Philadelphia Citizen, as credited by Historic South-View.',intro:'Horace Mann Bond was an educator and researcher who worked to improve education for Black students. He served as a university president and as dean of Atlanta University’s School of Education. He was also the father of civil rights leader Julian Bond.',chapters:[
 chapter('EDUCATION RESEARCH','Understanding what racism does.','Bond wrote about the effects of racism on Black students. His research joined academic work with the practical struggle to make educational opportunity more equal.','education'),
 chapter('1954','Research meets a landmark decision.','South-View credits Bond’s research with supporting Brown v. Board of Education, the decision that rejected racial segregation in public schools. This is a documented connection between his work and a larger historical event.','civic','Documented contribution','https://www.archives.gov/milestone-documents/brown-v-board-of-education')],legacy:'His institutional leadership, research, and family connections place Bond’s life within the history of Black education and the civil rights movement.'},
 {id:'jeanchildsyoung',name:'Jean Childs Young',role:'Educator & children’s advocate',group:'Education',credit:'Via African American Registry, as credited by Historic South-View.',intro:'Jean Childs Young developed early childhood curriculum in Atlanta Public Schools and wrote Bridging the Gap for parents. Her work connected learning at home with opportunity in schools, colleges, and museums.',chapters:[
 chapter('1979','Children on the public agenda.','The Smithsonian identified Young as national commission chair for the International Year of the Child in 1979. This places her own advocacy within an international effort to draw attention to children’s well-being.','education','Documented role','https://siarchives.si.edu/sites/default/files/pdfs/torch/Torch%201979/SIA_000371_1979_01.pdf'),
 chapter('1979–1981','Care in a city facing loss.','The Atlanta Child Murders took the lives of Black children, teenagers, and young adults. Young’s children’s rights work offers a thematic connection to care for young people. These sources do not establish a direct role in the crisis response or a relationship to victims.','children','Thematic community context','https://www.fbi.gov/history/field-office-histories/atlanta')],legacy:'Young’s story reaches beyond any single event through educational programs, institutions, and support for young people. Victims’ stories need their own research and community voices.'},
 {id:'johnwebowen',name:'John W. E. Bowen',role:'Theologian, educator & community leader',group:'Community',credit:'Via Philadelphia Citizen, as credited by Historic South-View.',intro:'John Wesley Edward Bowen was a scholar, teacher, and president of Gammon Theological Seminary. The first African American to earn a PhD at Boston University, he built a life around learning and public service. He and his wife Ariel Serena Hedges had four children.',chapters:[
 chapter('SCHOLARSHIP & LEADERSHIP','A place to teach and to learn.','Bowen taught subjects including Latin, Greek, mathematics, and theology. At Gammon, intellectual leadership and community responsibility became part of the same institutional life.','education','Documented life history','https://www.umc.org/en/content/bowen-john-wesley-edward-1855-1933'),
 chapter('SEPTEMBER 1906','A place of shelter in a city under attack.','During the Atlanta Race Massacre, Bowen offered Gammon as shelter for Black residents. He was himself beaten and arrested. The accompanying barbershop image represents another site connected to the same event; it is not an image of Bowen’s seminary.','massacre','Documented event connection','https://www.umc.org/en/content/bowen-john-wesley-edward-1855-1933')],legacy:'Bowen was a parent and scholar as well as a man who offered refuge. His teaching and community leadership continued beyond the violence of 1906.'},
 {id:'lillianmileslewis',name:'Lillian Miles Lewis',role:'Educator, librarian & political figure',group:'Education',credit:'FindAGrave contributor, as credited by Historic South-View.',intro:'Lillian Miles Lewis was an educator and librarian whose work helped shape Atlanta’s educational life. She moved to the city to work at Atlanta University and later contributed through Clark Atlanta University.',chapters:[
 chapter('ATLANTA UNIVERSITY','A life rooted in learning.','Her work as a librarian and educator forms a distinct chapter of her life. Institutions of learning brought her to Atlanta and remained part of the impact she made in the city.','education'),
 chapter('1986','Education and political life meet.','Lillian supported her husband John Lewis’s Atlanta City Council campaign and his 1986 congressional race. The source connects her directly to that political work, while also emphasizing her own educational contributions.','civic','Documented contribution')],legacy:'Her story should hold her own professional life alongside the partnership for which she is often remembered. Education, libraries, and political work all belong in that account.'}
];
